questionvariables.text:
/* Each row: [theta, x = cos(theta), y = sin(theta), quadrant, reference angle, degrees].
   Corrected: the Quadrant I rows (pi/6, pi/4, pi/3) previously had a negative x-coordinate. */
angles : [
    [%pi/6,     sqrt(3)/2,  1/2,        1, %pi/6,  30],
    [%pi/4,     sqrt(2)/2,  sqrt(2)/2,  1, %pi/4,  45],
    [%pi/3,     1/2,        sqrt(3)/2,  1, %pi/3,  60],
    [2*%pi/3,  -1/2,        sqrt(3)/2,  2, %pi/3,  120],
    [3*%pi/4,  -sqrt(2)/2,  sqrt(2)/2,  2, %pi/4,  135],
    [5*%pi/6,  -sqrt(3)/2,  1/2,        2, %pi/6,  150],
    [7*%pi/6,  -sqrt(3)/2, -1/2,        3, %pi/6,  210],
    [5*%pi/4,  -sqrt(2)/2, -sqrt(2)/2,  3, %pi/4,  225],
    [4*%pi/3,  -1/2,       -sqrt(3)/2,  3, %pi/3,  240],
    [5*%pi/3,   1/2,       -sqrt(3)/2,  4, %pi/3,  300],
    [7*%pi/4,   sqrt(2)/2, -sqrt(2)/2,  4, %pi/4,  315],
    [11*%pi/6,  sqrt(3)/2, -1/2,        4, %pi/6,  330]
];

variant : rand(angles);

theta : variant[1];
x0 : variant[2];
y0 : variant[3];
quad : variant[4];
refang : variant[5];
thetadeg : variant[6];
qnames : ["I", "II", "III", "IV"];
quadname : qnames[quad];
tanv : y0/x0;

ta : [x0, y0];
/* Possible student mistakes */
ta_mistake2 : [-x0, y0];                                   /* wrong sign of x */
ta_mistake3 : [x0, -y0];                                   /* wrong sign of y */
ta_mistake4 : [-x0, -y0];                                  /* both signs wrong: opposite quadrant */
ta_mistake5 : [y0, x0];                                    /* x and y swapped (sin and cos mixed up) */
ta_mistake6 : [signum(x0)*abs(y0), signum(y0)*abs(x0)];    /* right signs, cos/sin of the reference angle swapped */
